// Hyperliquid trading core — in-wallet, keys never leave the device.
//
// Signing follows the official Hyperliquid Python SDK byte for byte
// (hyperliquid/utils/signing.py), cross-checked against it in
// tests/test-hl.ts with golden vectors generated by the SDK itself:
//
// - L1 actions (order / cancel / updateLeverage / …) are NOT signed
//   directly. The action is msgpack-encoded, concatenated with the
//   nonce (8-byte big-endian), a vault marker byte (+ address when
//   trading for a vault/subaccount) and an optional expiresAfter
//   trailer, then keccak256-hashed. That hash becomes the
//   `connectionId` of a "phantom agent" EIP-712 message
//   (domain: name "Exchange", chainId 1337, version "1";
//   source "a" on mainnet, "b" on testnet).
// - approveAgent is a user-signed action: EIP-712 over
//   HyperliquidTransaction:ApproveAgent with domain
//   "HyperliquidSignTransaction" and signatureChainId 0x66eee
//   (the SDK sets this for both networks; hyperliquidChain carries
//   the Mainnet/Testnet distinction).
//
// The server only relays the finished, signed JSON to Hyperliquid's
// exchange endpoint — it never sees a key and never signs.
import { ethers } from 'ethers';
import { encode as msgpackEncode } from '@msgpack/msgpack';

export const HL_BRIDGE_ADDRESS = '0x2Df1c51E09aECF9cacB7bc98cB1742757f163dF7'; // Bridge2 on Arbitrum
export const HL_ARBITRUM_USDC = '0xaf88d065e77c8cC2239327C5EDb3A432268e5831'; // native Circle USDC on Arbitrum
export const HL_MIN_DEPOSIT_USDC = 5; // below this the bridge does not credit the deposit — funds are lost
export const HL_MIN_ORDER_USD = 10; // exchange-enforced minimum order value

// Perp asset id (official asset-ids doc): main dex = universe index;
// HIP-3 builder dex = 100000 + perpDexIndex * 10000 + universe index,
// where perpDexIndex is the dex's position in the perpDexs list
// (entry 0 is null — the main dex — so the first builder dex is 1).
export function hlAssetId(dexOrd: number, universeIdx: number): number {
  return dexOrd === 0 ? universeIdx : 100000 + dexOrd * 10000 + universeIdx;
}

// Port of the SDK's float_to_wire: 8-decimal fixed point, trailing
// zeroes stripped. Throws when the value cannot be represented
// exactly — a silently rounded price/size must never be signed.
export function floatToWire(x: number): string {
  if (!Number.isFinite(x)) throw new Error('float_to_wire: not finite');
  const rounded = x.toFixed(8);
  if (Math.abs(parseFloat(rounded) - x) >= 1e-12) throw new Error('float_to_wire causes rounding');
  let s = rounded;
  if (s.includes('.')) s = s.replace(/0+$/, '').replace(/\.$/, '');
  return s === '-0' || s === '' ? '0' : s;
}

// Hyperliquid perp price validity: at most 5 significant figures and
// at most (6 - szDecimals) decimal places (integer prices always
// allowed). Round to satisfy both before the value is wired.
export function hlRoundPrice(px: number, szDecimals: number): number {
  if (!(px > 0)) return 0;
  const maxDec = Math.max(0, 6 - szDecimals);
  const digits = Math.ceil(Math.log10(px));
  const sigPow = 5 - digits;
  let r = Math.round(px * Math.pow(10, sigPow)) / Math.pow(10, sigPow);
  const decPow = Math.pow(10, maxDec);
  r = Math.round(r * decPow) / decPow;
  return r;
}

// Sizes: at most szDecimals decimal places. `dir` 'down' never
// overspends (USD-sized entries, closes), 'round' is nearest.
export function hlRoundSize(sz: number, szDecimals: number, dir: 'down' | 'round' = 'round'): number {
  const p = Math.pow(10, szDecimals);
  const v = dir === 'down' ? Math.floor(sz * p) / p : Math.round(sz * p) / p;
  return v;
}

function nonceBytes(n: number): Uint8Array {
  const out = new Uint8Array(8);
  new DataView(out.buffer).setBigUint64(0, BigInt(n), false);
  return out;
}

// SDK action_hash: msgpack(action) || nonce(BE64) || vault marker
// (0x00, or 0x01 || 20-byte address) || [0x00 || expiresAfter(BE64)].
export function hlActionHash(action: unknown, nonce: number, vaultAddress: string | null = null, expiresAfter: number | null = null): string {
  const packed = msgpackEncode(action);
  const parts: Uint8Array[] = [packed, nonceBytes(nonce)];
  if (vaultAddress) {
    const vb = new Uint8Array(21); vb[0] = 1;
    vb.set(ethers.getBytes(ethers.getAddress(vaultAddress)), 1);
    parts.push(vb);
  } else parts.push(new Uint8Array([0]));
  if (expiresAfter != null) {
    const eb = new Uint8Array(9); eb[0] = 0;
    eb.set(nonceBytes(expiresAfter), 1);
    parts.push(eb);
  }
  const total = parts.reduce((s, p) => s + p.length, 0);
  const buf = new Uint8Array(total);
  let off = 0; for (const p of parts) { buf.set(p, off); off += p.length; }
  return ethers.keccak256(buf);
}

const L1_DOMAIN = { chainId: 1337, name: 'Exchange', verifyingContract: '0x0000000000000000000000000000000000000000', version: '1' } as const;
const L1_TYPES = { Agent: [{ name: 'source', type: 'string' }, { name: 'connectionId', type: 'bytes32' }] } as const;

export interface HlSignature { r: string; s: string; v: number }
function splitSig(sig: string): HlSignature {
  const s = ethers.Signature.from(sig);
  return { r: s.r, s: s.s, v: s.v };
}

export async function hlSignL1Action(privateKey: string, action: unknown, nonce: number, isMainnet = true, vaultAddress: string | null = null, expiresAfter: number | null = null): Promise<HlSignature> {
  const hash = hlActionHash(action, nonce, vaultAddress, expiresAfter);
  const wallet = new ethers.Wallet(privateKey);
  const sig = await wallet.signTypedData(
    { ...L1_DOMAIN },
    { Agent: [...L1_TYPES.Agent] },
    { source: isMainnet ? 'a' : 'b', connectionId: hash },
  );
  return splitSig(sig);
}

// Recovery counterpart (tests + local verification): rebuild the
// phantom-agent digest for an L1 action and recover the signer.
export function hlRecoverL1Signer(action: unknown, signature: HlSignature, nonce: number, isMainnet = true, vaultAddress: string | null = null, expiresAfter: number | null = null): string {
  const hash = hlActionHash(action, nonce, vaultAddress, expiresAfter);
  const digest = ethers.TypedDataEncoder.hash(
    { ...L1_DOMAIN },
    { Agent: [...L1_TYPES.Agent] },
    { source: isMainnet ? 'a' : 'b', connectionId: hash },
  );
  return ethers.recoverAddress(digest, { r: signature.r, s: signature.s, v: signature.v });
}

export const APPROVE_AGENT_TYPES = [
  { name: 'hyperliquidChain', type: 'string' },
  { name: 'agentAddress', type: 'address' },
  { name: 'agentName', type: 'string' },
  { name: 'nonce', type: 'uint64' },
] as const;
export const APPROVE_AGENT_PRIMARY = 'HyperliquidTransaction:ApproveAgent';

export interface HlApproveAgentAction {
  type: 'approveAgent';
  hyperliquidChain: 'Mainnet' | 'Testnet';
  signatureChainId: '0x66eee';
  agentAddress: string;
  agentName: string;
  nonce: number;
}

export function hlBuildApproveAgent(agentAddress: string, agentName: string, nonce: number, isMainnet = true): HlApproveAgentAction {
  return {
    type: 'approveAgent',
    hyperliquidChain: isMainnet ? 'Mainnet' : 'Testnet',
    signatureChainId: '0x66eee',
    agentAddress: agentAddress.toLowerCase(),
    agentName,
    nonce,
  };
}

const userSignedDomain = (signatureChainId: string) => ({
  name: 'HyperliquidSignTransaction',
  version: '1',
  chainId: parseInt(signatureChainId, 16),
  verifyingContract: '0x0000000000000000000000000000000000000000',
});

export async function hlSignApproveAgent(masterPrivateKey: string, action: HlApproveAgentAction): Promise<HlSignature> {
  const wallet = new ethers.Wallet(masterPrivateKey);
  const sig = await wallet.signTypedData(
    userSignedDomain(action.signatureChainId),
    { [APPROVE_AGENT_PRIMARY]: [...APPROVE_AGENT_TYPES] },
    { hyperliquidChain: action.hyperliquidChain, agentAddress: action.agentAddress, agentName: action.agentName, nonce: action.nonce },
  );
  return splitSig(sig);
}

export function hlRecoverApproveAgentSigner(action: HlApproveAgentAction, signature: HlSignature): string {
  const digest = ethers.TypedDataEncoder.hash(
    userSignedDomain(action.signatureChainId),
    { [APPROVE_AGENT_PRIMARY]: [...APPROVE_AGENT_TYPES] },
    { hyperliquidChain: action.hyperliquidChain, agentAddress: action.agentAddress, agentName: action.agentName, nonce: action.nonce },
  );
  return ethers.recoverAddress(digest, { r: signature.r, s: signature.s, v: signature.v });
}

// ---- wire actions -------------------------------------------------

export interface HlOrderWire {
  a: number; b: boolean; p: string; s: string; r: boolean;
  t: { limit: { tif: 'Alo' | 'Ioc' | 'Gtc' } } | { trigger: { isMarket: boolean; triggerPx: string; tpsl: 'tp' | 'sl' } };
  c?: string;
}

// Field order in these objects is load-bearing: the L1 signature
// hashes the msgpack encoding, whose map order follows insertion
// order — exactly as the SDK builds them.
export function hlOrderWire(o: {
  asset: number; isBuy: boolean; px: number; sz: number; reduceOnly: boolean;
  tif?: 'Alo' | 'Ioc' | 'Gtc';
  trigger?: { isMarket: boolean; triggerPx: number; tpsl: 'tp' | 'sl' };
  cloid?: string;
}): HlOrderWire {
  const w: HlOrderWire = {
    a: o.asset, b: o.isBuy, p: floatToWire(o.px), s: floatToWire(o.sz), r: o.reduceOnly,
    t: o.trigger
      ? { trigger: { isMarket: o.trigger.isMarket, triggerPx: floatToWire(o.trigger.triggerPx), tpsl: o.trigger.tpsl } }
      : { limit: { tif: o.tif || 'Gtc' } },
  };
  if (o.cloid) w.c = o.cloid;
  return w;
}

export function hlOrderAction(orders: HlOrderWire[], grouping: 'na' | 'normalTpsl' | 'positionTpsl' = 'na'): Record<string, unknown> {
  return { type: 'order', orders, grouping };
}

export function hlUpdateLeverageAction(asset: number, isCross: boolean, leverage: number): Record<string, unknown> {
  return { type: 'updateLeverage', asset, isCross, leverage };
}

export function hlCancelAction(cancels: { a: number; o: number }[]): Record<string, unknown> {
  return { type: 'cancel', cancels };
}

// Estimated liquidation price for the review sheet — isolated-margin
// approximation with Hyperliquid's first-tier maintenance margin
// (half the initial margin at max leverage). Labelled an estimate in
// the UI; the authoritative figure is the API's liquidationPx once a
// position exists.
export function hlEstLiqPx(entryPx: number, isLong: boolean, leverage: number, maxLeverage: number): number {
  const mmf = 1 / (2 * Math.max(1, maxLeverage));
  const f = 1 / Math.max(1, leverage) - mmf;
  return isLong ? entryPx * (1 - f) : entryPx * (1 + f);
}

// ---- transport (through our own server's dumb relay) ---------------

export async function hlInfo(body: Record<string, unknown>): Promise<any> {
  // Bounded like every other fetcher in the app: an unbounded fetch
  // here froze the whole HL surface when the relay stalled (the
  // WalletConnect freeze class).
  const r = await fetch('/api/hl/info', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body), signal: AbortSignal.timeout(15000) });
  const j = await r.json().catch(() => null);
  if (!r.ok) throw new Error(j?.error || `Hyperliquid info failed (${r.status})`);
  return j;
}

export async function hlExchange(payload: Record<string, unknown>): Promise<any> {
  let r: Response;
  try {
    r = await fetch('/api/hl/exchange', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload), signal: AbortSignal.timeout(25000) });
  } catch {
    // A timeout here means the outcome is UNKNOWN (the action may
    // have landed) — say exactly that, never a plain failure.
    throw new Error('Hyperliquid did not answer in time — the action may still have gone through. Check your positions and orders before retrying.');
  }
  const j = await r.json().catch(() => null);
  if (!r.ok) throw new Error(typeof j === 'string' ? j : j?.error || `Hyperliquid exchange failed (${r.status})`);
  if (j?.status === 'err') throw new Error(typeof j.response === 'string' ? j.response : 'Hyperliquid rejected the action');
  return j;
}

// Monotonic nonce source. Two actions signed in the same
// millisecond (approve-agent immediately followed by an order, a
// fast cancel after an order) used to share a Date.now() nonce and
// Hyperliquid rejected the second as a duplicate — an intermittent
// failure that looked random. Nonces now strictly increase.
let lastNonce = 0;
export function hlNonce(): number {
  const n = Date.now();
  lastNonce = n > lastNonce ? n : lastNonce + 1;
  return lastNonce;
}

// Sign an L1 action with the agent key and relay it. Returns the
// exchange response ({status:'ok', response:{…}}).
export async function hlPostL1(agentPrivateKey: string, action: Record<string, unknown>, isMainnet = true): Promise<any> {
  const nonce = hlNonce();
  const signature = await hlSignL1Action(agentPrivateKey, action, nonce, isMainnet);
  return hlExchange({ action, nonce, signature });
}

// Approve the agent wallet: signed by the MASTER key (user-signed
// action), relayed once; afterwards the agent key trades alone.
export async function hlApproveAgent(masterPrivateKey: string, agentAddress: string, agentName: string, isMainnet = true): Promise<any> {
  const nonce = hlNonce();
  const action = hlBuildApproveAgent(agentAddress, agentName, nonce, isMainnet);
  const signature = await hlSignApproveAgent(masterPrivateKey, action);
  return hlExchange({ action, nonce, signature });
}

// Summarise an order response into user-facing lines: filled /
// resting / per-order errors, verbatim from the exchange.
export function hlOrderStatusLines(res: any): string[] {
  const statuses = res?.response?.data?.statuses;
  if (!Array.isArray(statuses)) return ['Order sent — no status returned.'];
  return statuses.map((st: any) => {
    if (st?.filled) return `Filled ${st.filled.totalSz} @ ${st.filled.avgPx} (order ${st.filled.oid})`;
    if (st?.resting) return `Resting on the book (order ${st.resting.oid})`;
    if (st?.error) return String(st.error);
    return 'Order sent.';
  });
}
